def decimal_to_binary(decimal: int) -> str:
    if decimal < 0:
        raise ValueError("Input must be a non-negative integer.")

    binary_representation = bin(decimal)[2:]  # Get binary representation and strip the '0b' prefix
    result = f"db{binary_representation}db"  # Format the result with 'db' prefix and suffix
    return result

